package com.quizplatform.model;
import java.time.LocalDateTime;
/** Records one participant's progress and final score for a quiz. */
public class QuizAttempt { private long id,quizId,participantId; private int score,totalPoints; private String status; private LocalDateTime startedAt,submittedAt;
 public QuizAttempt(long id,long quizId,long participantId,int score,int totalPoints,String status,LocalDateTime startedAt,LocalDateTime submittedAt){this.id=id;this.quizId=quizId;this.participantId=participantId;this.score=score;this.totalPoints=totalPoints;this.status=status;this.startedAt=startedAt;this.submittedAt=submittedAt;}
 public long getId(){return id;} public void setId(long v){id=v;} public long getQuizId(){return quizId;} public void setQuizId(long v){quizId=v;} public long getParticipantId(){return participantId;} public void setParticipantId(long v){participantId=v;} public int getScore(){return score;} public void setScore(int v){score=v;} public int getTotalPoints(){return totalPoints;} public void setTotalPoints(int v){totalPoints=v;} public String getStatus(){return status;} public void setStatus(String v){status=v;} public LocalDateTime getStartedAt(){return startedAt;} public void setStartedAt(LocalDateTime v){startedAt=v;} public LocalDateTime getSubmittedAt(){return submittedAt;} public void setSubmittedAt(LocalDateTime v){submittedAt=v;}}
